'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled PrizeEntry, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './prize-entry.css'
// The shared rule sets, for the same reason as in form.tsx: this surface
// renders actions, so the file that carries the action type and the press
// gesture ships with it (GSUI-118).
import '../../../tokens/primitives.css'

// The flat install layout puts every component in one directory, so these
// specifiers have to read `./form`. See hud/score.ts, which explains it first.
import { Form } from './form'
import { Field } from './field'
import { Button } from './button'
import { TickGlyph } from './glyphs'

/**
 * PrizeEntry: the draw entry form, and the state after it. BDS-041.
 *
 * REQ-051 asks for the path from login to code to entry to **entered**, so the
 * confirmation is part of this component rather than a screen the host is left
 * to invent. Pass `entered` and it renders the state the player is now in: they
 * are in the draw, this is their entry number, this is when it is drawn.
 *
 * **Consent is never assumed.** No box here starts ticked, by construction:
 * there is no prop that would tick one and no default that could. Required and
 * optional are stated in words beside each box, and the entry control stays
 * unavailable until every required box is ticked, so the player cannot enter a
 * draw whose terms they have not accepted and cannot be told afterwards that
 * they did.
 *
 * It enters nobody into anything. It collects the fields and the consents and
 * hands them to the host, which runs the draw.
 */

/** One thing the player is asked to agree to. Never ticked by the component. */
export interface PrizeConsent {
  /** Its name in the values handed to `onSubmit`, and on `data-gs-field`. */
  name: string
  /** What they are agreeing to, in the host's words. May carry a link. */
  label: React.ReactNode
  /**
   * Whether the entry depends on it. `required` keeps the entry control
   * unavailable until it is ticked; `optional` never blocks anything. Both are
   * written beside the box as a word.
   */
  requirement: 'required' | 'optional'
}

/** What the player is playing for. Rendered above the fields. */
export interface PrizeEntryPrize {
  /** "Enter the draw", or whatever this draw is called. */
  title: React.ReactNode
  /** "Win a signed race suit". The thing itself. */
  detail?: React.ReactNode
  /** The host's artwork for it. Any node; the component draws no prize itself. */
  art?: React.ReactNode
}

export interface PrizeEntryProps {
  /** What the player is entering for. */
  prize: PrizeEntryPrize
  /** The fields, usually prefilled from whatever sign-in gave the host. */
  children?: React.ReactNode
  /** What the player is asked to agree to, in the order given. */
  consents?: PrizeConsent[]
  /** What the entry control says once every required consent is given. */
  submitLabel?: React.ReactNode
  /** What it says while it is still waiting for one. Says what to do, not "no". */
  blockedLabel?: React.ReactNode
  /** The fields and the consents, handed over. The host runs the draw. */
  onSubmit?: (values: Record<string, string>) => void
  /** The host has been asked and has not answered. Host-declared. */
  busy?: boolean
  /** What the host rejected, as sentences. Rendered above the fields. */
  errors?: { field: string; reason: string }[]
  /** The player is in. Renders the entered state instead of the form. */
  entered?: boolean
  /** What the entered state says, once the host knows. */
  entry?: {
    /** "You're in". */
    title?: React.ReactNode
    /** "Entry #4,812. Winner drawn Sunday after the race. We'll email you." */
    detail?: React.ReactNode
    /** A standing fact worth keeping on screen: "+1 entry per streak day". */
    note?: React.ReactNode
  }
  /** What the way out of the entered state says. */
  doneLabel?: React.ReactNode
  /** The player is finished with this surface. Omit it and no way out renders. */
  onDone?: () => void
}

const DEFAULTS = {
  submitLabel: 'Enter the draw',
  blockedLabel: 'Accept terms to enter',
  enteredTitle: "You're in",
  doneLabel: 'Back to the game',
} as const


export function PrizeEntry({
  prize,
  children,
  consents = [],
  submitLabel = DEFAULTS.submitLabel,
  blockedLabel = DEFAULTS.blockedLabel,
  onSubmit,
  busy = false,
  errors,
  entered = false,
  entry,
  doneLabel = DEFAULTS.doneLabel,
  onDone,
}: PrizeEntryProps) {
  // Which boxes are ticked, held in memory for as long as the form is on screen
  // and written nowhere. It starts empty, and there is no way for a caller to
  // start it otherwise: a pre-ticked consent box is consent nobody gave.
  const [given, setGiven] = React.useState<Record<string, boolean>>({})

  const required = consents.filter((consent) => consent.requirement === 'required')
  const outstanding = required.filter((consent) => !given[consent.name])
  const blocked = outstanding.length > 0

  const title = typeof prize.title === 'string' ? prize.title : DEFAULTS.submitLabel

  if (entered) {
    return (
      <section
        className="gs-prize-entry"
        data-gs-component="prize-entry"
        // The state the player is now in, rather than a screen the host invents.
        data-gs-complete="true"
        aria-label={title}
      >
        <div className="gs-prize-entry__entered">
          <span
            className="gs-prize-entry__seal"
            data-gs-scope="prize-entry"
            data-gs-part="seal"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            <TickGlyph />
          </span>
          <h2 className="gs-prize-entry__title" data-gs-scope="prize-entry" data-gs-part="label">
            {entry?.title ?? DEFAULTS.enteredTitle}
          </h2>
          {entry?.detail ? (
            <p className="gs-prize-entry__detail" data-gs-scope="prize-entry" data-gs-part="detail">
              {entry.detail}
            </p>
          ) : null}
          {entry?.note ? (
            <p className="gs-prize-entry__note" data-gs-scope="prize-entry" data-gs-part="note">
              {entry.note}
            </p>
          ) : null}
          {onDone ? (
            <Button
              className="gs-prize-entry__done"
              data-gs-scope="prize-entry"
              data-gs-part="done"
              onClick={() => onDone()}
            >
              {doneLabel}
            </Button>
          ) : null}
        </div>
      </section>
    )
  }

  return (
    <section className="gs-prize-entry" data-gs-component="prize-entry" aria-label={title}>
      <div className="gs-prize-entry__prize">
        {prize.art ? (
          <span className="gs-prize-entry__art" data-gs-scope="prize-entry" data-gs-part="media">
            {prize.art}
          </span>
        ) : null}
        <span className="gs-prize-entry__prizetext">
          <h2 className="gs-prize-entry__title" data-gs-scope="prize-entry" data-gs-part="label">
            {prize.title}
          </h2>
          {prize.detail ? (
            <p className="gs-prize-entry__detail" data-gs-scope="prize-entry" data-gs-part="detail">
              {prize.detail}
            </p>
          ) : null}
        </span>
      </div>

      <Form
        name="prize-entry"
        label={title}
        busy={busy}
        errors={errors}
        onSubmit={(values) => {
          if (blocked) return
          onSubmit?.(values)
        }}
        actions={
          <Button
            type="submit"
            // Unavailable rather than hidden, and it says what to do rather than
            // saying no: a control that only greys out leaves the player
            // guessing which box they missed.
            disabled={blocked || busy}
            data-gs-scope="prize-entry"
            data-gs-part="commit"
          >
            {blocked ? blockedLabel : submitLabel}
          </Button>
        }
      >
        {children}
        {consents.map((consent) => (
          <Field
            key={consent.name}
            name={consent.name}
            control="checkbox"
            label={consent.label}
            requirement={consent.requirement}
            checked={given[consent.name] ?? false}
            onChange={(event) =>
              setGiven((was) => ({ ...was, [consent.name]: event.target.checked }))
            }
          />
        ))}
      </Form>
    </section>
  )
}

/* PrizeEntry. Every value comes from a token; nothing here is a literal colour.

   Specimen 4c's third and fourth cards draw this surface, entry and entered,
   and design/twins/4c.json measures ours against both. */

.gs-prize-entry {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-4);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* -- what they are playing for --------------------------------------------- */
.gs-prize-entry__prize {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
}

/* The prize mark: a 52px disc in the drawing, which is size.chip exactly,
   ringed in the control stroke, on the reward colour with the reward glow. */
.gs-prize-entry__art {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-chip);
  block-size: var(--gs-size-chip);
  box-sizing: border-box;
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  overflow: hidden;
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
  box-shadow: var(--gs-depth-reward);
}

.gs-prize-entry__prizetext {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-inline-size: 0;
}

/* The title scale, in capitals, as every heading on these cards. The drawing
   draws this one at 15px beside the mark and the entered one at 24; the token
   is 20 and the twins file records both. */
.gs-prize-entry__title {
  margin: 0;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

/* The line under it, in the caption token. */
.gs-prize-entry__detail {
  margin: 0;
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;
}

/* -- consent --------------------------------------------------------------- */
/* A consent sentence is the caption token in the drawing, 600 at 11px on the
   secondary ink, which is what lets two of them and three fields share a
   300px card with the action. The box beside it is field's own. */
.gs-prize-entry .gs-field__tickrow .gs-field__label {
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  padding-block-start: 0;
}

/* -- entered --------------------------------------------------------------- */
/* The state the player is in after the host says they are in. Centred, because
   there is one thing to read and nothing to do. */
.gs-prize-entry__entered {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--gs-space-3);
}

/* Emphasis, not motion: the seal appears and holds. A player with reduced
   motion still sees the difference between entered and not entered. The
   drawing draws it at 110px; icon-hero at 64 is the largest size token. */
.gs-prize-entry__seal {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-hero);
  block-size: var(--gs-size-icon-hero);
  box-sizing: border-box;
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
  font-size: var(--gs-size-icon-control);
  box-shadow: var(--gs-depth-reward);
}

/* "You're in" carries the display shadow: it is the one headline on these
   cards the drawing draws with the full 3px shadow. */
.gs-prize-entry__entered .gs-prize-entry__title {
  text-shadow: var(--gs-type-display-shadow, none);
}

/* A standing fact, kept on screen as a pill: the chip treatment, the dark
   edge fill ringed in the high edge, the figure face inside. */
.gs-prize-entry__note {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
  margin: 0;
  min-block-size: var(--gs-size-control-medium);
  box-sizing: border-box;
  padding: 0 var(--gs-space-4);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  border: var(--gs-stroke-control) solid var(--gs-color-edge-high);
  color: var(--gs-color-ink);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  /* One line, as a chip is: a standing fact is short, and a pill that wraps
     is a paragraph in a box. */
  white-space: nowrap;
}

.gs-prize-entry .gs-prize-entry__done {
  inline-size: 100%;
  margin-block-start: var(--gs-space-2);
}
